import { VBI } from '@visactor/vbi'
import { VSeedRender } from '@components'
import { useEffect, useState } from 'react'

export default () => {
  const [vseed, setVSeed] = useState(null)

  useEffect(() => {
    const run = async () => {
      const schema = [
        { name: 'sales', type: 'number' },
        { name: 'profit', type: 'number' },
      ]
      const dataset = [
        { sales: 100, profit: 100 },
        { sales: 200, profit: 200 },
        { sales: 300, profit: 300 },
        { sales: 400, profit: 400 },
        { sales: 500, profit: 500 },
      ]

      VBI.registerConnector('demo', async () => ({
        discoverSchema: async () => schema,
        query: async () => ({ dataset }),
      }))

      const builder = VBI.from({
        connectorId: 'demo',
        chartType: 'scatter',
        dimensions: [],
        measures: [
          { field: 'sales', alias: '销售额', encoding: 'x', aggregate: { func: 'sum' } },
          { field: 'profit', alias: '利润', encoding: 'y', aggregate: { func: 'sum' } },
        ],
        filters: [],
        theme: 'light',
        locale: 'zh-CN',
        version: 1,
      })

      const applyBuilder = (builder: VBIBuilder) => {
        builder.chartType.changeChartType('bar')
      }
      applyBuilder(builder)

      const result = await builder.buildVSeed()
      setVSeed(result)
    }
    run()
  }, [])

  if (!vseed) return <div>Loading...</div>

  return <VSeedRender vseed={vseed} />
}